INSERT INTO `hoa_aura` (`entry`, `key`, `icon`, `name`, `description`, `stack_max`, `duration_index`, `visible`, `dynamic_kind`, `dynamic_template`, `source_kind`, `source_id`)
VALUES
  (12485, 'keyword_chill', 'Interface\\Icons\\Spell_Frost_IceStorm', 'Chill', 'Slows the enemy by 3% per stack, up to 30%. At 10 stacks the enemy becomes Frozen. An enemy that can''t be Frozen yet stays at 10 stacks. Each new stack refreshes Chill to 4 sec.', 10, 28, 1, 0, '', 'keyword', 1),
  (18798, 'keyword_frozen', 'Interface\\Icons\\Spell_Frost_Glacier', 'Frozen', 'Normal enemies are frozen in place for 2 sec. Elites and bosses keep moving but count as Frozen for those 2 sec. Shatter: your Frost spells always critically strike Frozen enemies, and every critical strike against a Frozen enemy deals an extra 50% damage. After a Freeze, that enemy can''t be Frozen again for 6 sec.', 1, 28, 1, 0, '', 'keyword', 2),
  (12654, 'keyword_burning', 'Interface\\Icons\\Spell_Fire_Incinerate', 'Burning', 'Each stack deals Fire damage every tick. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a burning enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards, and the damage its stacks had left bursts onto up to 4 enemies within 8 yards, half on each.', 30, 28, 1, 0, '', 'keyword', 3),
  (12721, 'keyword_bleed', 'Interface\\Icons\\Ability_BackStab', 'Bleed', 'Each stack deals Physical damage every tick. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a bleeding enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards, and the damage its stacks had left bursts onto up to 4 enemies within 8 yards, half on each.', 30, 28, 1, 0, '', 'keyword', 4),
  (19448, 'keyword_poison', 'Interface\\Icons\\Spell_Nature_CorrosiveBreath', 'Poison', 'Each stack deals Nature damage every tick. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a poisoned enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards, and the damage its stacks had left bursts onto up to 4 enemies within 8 yards, half on each.', 30, 28, 1, 0, '', 'keyword', 5),
  (22959, 'keyword_fire_vulnerability', 'Interface\\Icons\\Spell_Fire_SoulBurn', 'Fire Vulnerability', 'Increases Fire damage taken by 3% per stack. Stacks up to 5 times.', 5, 28, 1, 0, '', 'keyword', 6),
  (27991, 'keyword_sunder_armor', 'Interface\\Icons\\Ability_Warrior_Sunder', 'Sunder Armor', 'Increases Physical damage taken by 4% per stack. Stacks up to 5 times.', 5, 28, 1, 0, '', 'keyword', 7),
  (15258, 'keyword_shadow_vulnerability', 'Interface\\Icons\\Spell_Shadow_BlackPlague', 'Shadow Vulnerability', 'Increases Shadow damage taken by 3% per stack. Stacks up to 5 times.', 5, 28, 1, 0, '', 'keyword', 8),
  (20374, 'keyword_hunters_mark', 'Interface\\Icons\\Ability_Hunter_SniperShot', 'Hunter''s Mark', 'Marked enemies take 15% more damage from you and your summons, raised by the marking spell''s ranks and Mark upgrades up to 30%. Talents add on top. When a Marked enemy dies, the Mark passes to the 2 nearest unmarked enemies within 10 yards.', 1, 28, 1, 0, '', 'keyword', 9),
  (13496, 'keyword_dazed', 'Interface\\Icons\\Spell_Frost_Stun', 'Dazed', 'Slows the enemy by 30% for 4 sec.', 1, 28, 1, 0, '', 'keyword', 10),
  (18148, 'keyword_static', 'Interface\\Icons\\Spell_Nature_Lightning', 'Static', 'Stacks up to 5 times. At 5 stacks, the enemy is struck by lightning, dealing Nature damage to it and up to 3 enemies within 6 yards, and the stacks reset.', 5, 28, 1, 0, '', 'keyword', 11),
  (17364, 'keyword_nature_vulnerability', 'Interface\\Icons\\Spell_Holy_SealOfMight', 'Nature Vulnerability', 'Increases Nature damage taken by 4% per stack. Stacks up to 5 times.', 5, 28, 1, 0, '', 'keyword', 12),
  (594, 'keyword_decay', 'Interface\\Icons\\Spell_Shadow_ChillTouch', 'Decay', 'Each stack deals Shadow damage every tick. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a decaying enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards.', 30, 28, 1, 0, '', 'keyword', 13),
  (14868, 'keyword_agony', 'Interface\\Icons\\Spell_Shadow_CurseOfSargeras', 'Agony', 'Each stack deals Shadow damage every tick. A stack''s damage grows by a quarter of its starting damage every tick it stays on, up to triple after 8 ticks. One curse per enemy.', 30, 28, 1, 0, '', 'keyword', 14),
  (8921, 'keyword_moonfire', 'Interface\\Icons\\Spell_Nature_StarFall', 'Moonfire', 'Each stack deals Arcane damage every tick. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a moonfired enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards.', 30, 28, 1, 0, '', 'keyword', 15),
  (17, 'shielded_state', '', 'Shielded', 'You move 10% faster while shielded.', 0, 0, 1, 0, '', 'none', NULL),
  (5277, 'evasion_window', 'Interface\\Icons\\Spell_Shadow_ShadowWard', 'Evasion', 'Increases your dodge chance by 50% for 5 sec, up to 85%.', 0, 28, 1, 0, '', 'weapon', 611),
  (8233, 'doom_winds_window', 'Interface\\Icons\\Spell_Nature_Cyclone', 'Doom Winds', 'Swings at the nearest enemy for damage. Every 3rd swing calls Windfury: 2 extra swings that also hit enemies within 4 yards. Every 15 sec, every swing calls Windfury for 4 sec.', 0, 28, 1, 0, '', 'weapon', 721),
  (33461, 'souls_state', '', 'Souls', 'You deal 5% more damage for each soul.', 10, 28, 1, 0, '', 'none', NULL),
  (60056, 'necrotic_state', 'Interface\\Icons\\Spell_Shadow_AbominationExplosion', 'Necrotic', 'Healing received reduced by 5% per stack.', 15, 28, 1, 2, 'Healing received reduced by {1}.', 'none', NULL),
  (339, 'rooted_state', '', 'Rooted', 'Rooted for 2 sec.', 0, 28, 1, 0, '', 'none', NULL),
  (1833, 'cheap_shot_state', 'Interface\\Icons\\Ability_CheapShot', 'Cheap Shot', 'Your first hit on each enemy with your other abilities is followed by an Ambush for heavy damage, with double critical strike chance. Ambush stuns normal enemies for 1 sec.', 0, 28, 1, 0, '', 'weapon', 630),
