  (20368, 'raging_state', '', 'Raging', 'Damage increased.', 0, 0, 1, 0, '', 'none', NULL),
  (21183, 'judged_state', 'Interface\\Icons\\Spell_Holy_HolySmite', 'Judgement of the Crusader', 'Slams the 3 strongest enemies within 20 yards with a hammer of light for Holy damage, with double critical strike chance. Judged enemies take 20% more damage from you for 6 sec. Releases your Seals like Judgement.', 0, 28, 1, 0, '', 'weapon', 818),
  (23414, 'void_tendrils_state', 'Interface\\Icons\\Spell_Shadow_Twilight', 'Void Tendrils', 'Summons a Shadowfiend whose attacks apply Decay and heal you for 0.5% of your maximum health. Every 6 sec it roots normal enemies within 6 yards for 2 sec.', 0, 28, 1, 0, '', 'weapon', 535),
  (19502, 'pet_plague', 'Interface\\Icons\\Ability_Creature_Disease_02', 'Plague Beast', 'Summons an undead beast to fight for you. Its Claw applies 2 stacks of Poison, and its plague cloud adds 1 stack of Poison every sec to enemies within 5 yards.', 0, 0, 1, 0, '', 'weapon', 229),
  (19574, 'pet_bestial_wrath', 'Interface\\Icons\\Ability_Druid_FerociousBite', 'Bestial Wrath', 'Your pets are always frenzied: +50% damage, and their attacks hit every enemy in front of them. Pack Leader''s howl makes them deal 25% more. Your other spells deal 25% less damage.', 0, 0, 1, 0, '', 'mastery', 30110),
  (28419, 'pet_screech', '', 'Screech', 'The Wyvern''s screech strengthens your pets.', 0, 0, 1, 0, '', 'none', NULL),
