  (33467, 'deterrence_window', '', 'Deterrence', 'Dodge chance increased by 50%.', 0, 28, 1, 0, '', 'none', NULL),
  (33468, 'revived_window', '', 'Revived', 'Immune to physical damage.', 0, 28, 1, 0, '', 'none', NULL),
  (33463, 'divine_shield_window', 'Interface\\Icons\\Spell_Holy_DivineIntervention', 'Divine Shield', 'A golden bubble forms around you and blocks the next enemy hit that would take more than 5% of your maximum health.', 0, 28, 1, 0, '', 'weapon', 809),
  (33464, 'renew_window', 'Interface\\Icons\\Spell_Holy_Renew', 'Renew', 'Heals you for 1% of your maximum health every sec. At full health, it smites the nearest enemy within 30 yards for Holy damage instead. With Power Word: Shield, healing past full health tops up your Shield, up to its size.', 0, 28, 1, 0, '', 'weapon', 501),
  (33465, 'lightning_shield_window', 'Interface\\Icons\\Spell_Nature_LightningShield', 'Lightning Shield', 'Surrounds you with up to 3 lightning charges. Every 1.5 sec it zaps 1 enemy within 10 yards for each charge you hold, dealing Nature damage and 1 stack of Static, and each zap gives you a Shield of 0.5% of your maximum health, up to 5%. An enemy that strikes you spends a charge and is zapped too. One charge returns every 1.5 sec.', 0, 28, 1, 0, '', 'weapon', 711),
  (33466, 'blade_flurry_window', 'Interface\\Icons\\Ability_Warrior_PunishingBlow', 'Blade Flurry', 'Your single-target hits also strike 4 more enemies within 8 yards at 50% damage for 8 sec. The extra hits carry your poisons and openers.', 0, 28, 1, 0, '', 'weapon', 601),
  (60001, 'determination', 'Interface\\Icons\\Spell_Holy_DevotionAura', 'Determination', 'Each stack increases your Power and reduces the damage you take.', 5, 0, 1, 3, '+{1} Power and {1}% less damage taken.', 'none', NULL),
  (60003, 'wounds', 'Interface\\Icons\\Ability_Warrior_SavageBlow', 'Boss Wounds', 'Reduces the healing you receive.', 4, 28, 1, 2, 'Healing received reduced by {1}.', 'none', NULL),
  (60004, 'darkmoon_surge', 'Interface\\Icons\\INV_Jewelry_Talisman_10', 'Zandalarian Hero Charm', 'Every 30 sec, gain 25% Power for 10 sec.', 255, 28, 1, 4, 'Power increased by {1}%.', 'card', 21),
  (60005, 'shield', 'Interface\\Icons\\Spell_Holy_PowerWordShield', 'Shield', 'Absorbs incoming damage.', 0, 0, 1, 1, 'Absorbs {1} damage.', 'none', NULL),
  (60057, 'shield_regen', 'Interface\\Icons\\Spell_Holy_PowerWordShield', 'Shield Regenerating', 'Shield will regenerate when you avoid damage.', 0, 28, 1, 3, 'Shield regenerates in {1} sec.', 'none', NULL),
  (60058, 'bladestorm_window', 'Interface\\Icons\\Ability_Whirlwind', 'Spinning Blades', 'Spinning, striking all nearby enemies.', 0, 28, 1, 3, 'Spinning for {1} sec. Strikes every {2} sec.', 'weapon', 323),
  (60059, 'consecration_might', 'Interface\\Icons\\Spell_Holy_AuraOfLight', 'Consecrated Might', 'Damage increased while standing in Consecration.', 0, 0, 1, 3, 'Damage increased by {1}%.', 'none', NULL),
  (60060, 'consecration_guard', 'Interface\\Icons\\Spell_Holy_SealOfProtection', 'Guardian of the Light', 'Damage taken reduced while standing in Consecration.', 0, 0, 1, 3, 'Damage taken reduced by {1}%.', 'none', NULL),
  (60061, 'counterattack_cooldown', 'Interface\\Icons\\Ability_Warrior_Challange', 'Counterattack', 'Counterattack cannot trigger yet.', 0, 28, 1, 3, 'Counterattack triggers again in {1} sec.', 'none', NULL),
  (60062, 'shadow_weaving_cooldown', 'Interface\\Icons\\Spell_Shadow_BlackPlague', 'Shadow Weaving', 'Shadow Weaving cannot trigger yet.', 0, 28, 1, 3, 'Shadow Weaving triggers again in {1} sec.', 'none', NULL),
  (60063, 'shamanistic_rage_cooldown', 'Interface\\Icons\\Spell_Nature_UnyeildingStamina', 'Shamanistic Rage', 'Shamanistic Rage cannot trigger yet.', 0, 28, 1, 3, 'Shamanistic Rage triggers again in {1} sec.', 'none', NULL),
  (60064, 'improved_frost_nova_cooldown', 'Interface\\Icons\\Spell_Frost_FreezingBreath', 'Improved Frost Nova', 'Improved Frost Nova cannot trigger yet.', 0, 28, 1, 3, 'Improved Frost Nova triggers again in {1} sec.', 'none', NULL),
  (60006, 'card_haste', 'Interface\\Icons\\INV_Misc_Ticket_Tarot_BlueDragon_01', 'Darkmoon Card: Blue Dragon', 'Your spells have a 10% chance to grant 30% Haste for 6 sec. 20 sec cooldown.', 1, 28, 1, 4, '', 'card', 35),
  (60007, 'card_swift', 'Interface\\Icons\\INV_Potion_95', 'Swiftness Potion', 'When you drop below 50% health, run 50% faster for 4 sec. 20 sec cooldown.', 0, 28, 1, 4, '', 'card', 14),
  (60008, 'card_immune', 'Interface\\Icons\\INV_Jewelry_TrinketPVP_01', 'Insignia of the Alliance', 'After you are hit, take no damage for 0.5 sec. 8 sec cooldown.', 0, 28, 1, 4, '', 'card', 13),
  (60010, 'card_thorns', 'Interface\\Icons\\INV_Jewelry_Necklace_04', 'Barbed Choker', 'When an enemy hits you, thorns strike all enemies within 8 yards for 40% of a normal enemy''s health on Normal. Once every 0.5 sec.', 255, 0, 1, 4, '', 'card', 12),
  (60012, 'tigers_fury', 'Interface\\Icons\\Ability_Mount_JungleTiger', 'Tiger''s Fury', 'Rakes the 3 nearest enemies for damage and 2 stacks of Bleed. Empowered in Cat Form. Each Rake grants 5% Haste per enemy hit for 4 sec, up to 25%.', 0, 28, 1, 0, '', 'weapon', 1021),
  (60013, 'arcane_power', 'Interface\\Icons\\Spell_Nature_Lightning', 'Arcane Power', 'Launches 5 Arcane Missiles at the nearest enemy over 1 sec, each dealing Arcane damage, 50% more to elites, mini-bosses and bosses. After each Blink, it fires all 5 at once at the nearest enemies and your spells deal 30% more damage for 4 sec.', 0, 28, 1, 0, '', 'weapon', 430),
  (60014, 'shadow_dance', 'Interface\\Icons\\Spell_Shadow_Charm', 'Shadow Dance', 'Your hits deal 30% more damage for 4 sec and can set off Ambush again, once a sec per enemy.', 0, 28, 1, 0, '', 'weapon', 610),
  (60015, 'envenom', 'Interface\\Icons\\Ability_Creature_Poison_06', 'Envenom', 'Strikes the 3 enemies with the most Poison for Nature damage plus all the damage their Poison would still deal, keeping their stacks. Your hits apply 2 more stacks of Poison for 5 sec.', 0, 28, 1, 0, '', 'weapon', 607),
  (60016, 'dark_pact', 'Interface\\Icons\\Spell_Shadow_DarkRitual', 'Dark Pact', 'Drains the nearest enemy within 16 yards, dealing damage every sec and healing you, up to 2% of your maximum health a sec. Healing past full health makes your demons deal 30% more damage for 4 sec. Drained enemies take 20% more damage from your Decay and Agony.', 0, 28, 1, 0, '', 'weapon', 924),
  (60017, 'soul_harvest', 'Interface\\Icons\\INV_Misc_Gem_Amethyst_02', 'Glyph of Soul Harvest', 'Every 50 kills, you deal triple damage for 2 sec.', 0, 28, 1, 0, '', 'glyph', 12),
  (60018, 'glyph_haste', 'Interface\\Icons\\Spell_Holy_RighteousFury', 'Glyph of Bloodlust', 'Every 50 kills, gain 40% Haste for 8 sec.', 0, 28, 1, 0, '', 'glyph', 8),
  (60019, 'ice_block', 'Interface\\Icons\\Spell_Frost_Frost', 'Ice Block', 'Once per stage, dropping below 20% health encases you in ice: you take no damage for 2 sec, and enemies within 10 yards gain 10 stacks of Chill. Can''t be learned with Improved Frost Nova.', 0, 28, 1, 0, '', 'mastery', 80307),
  (60020, 'nomad', 'Interface\\Icons\\Ability_Rogue_Sprint', 'Glyph of the Nomad', 'Losing health flips it to -25% Power for 5 sec. Shield absorbs don''t count.', 0, 28, 1, 0, '', 'glyph', 27),
  (60021, 'kill_power', 'Interface\\Icons\\INV_Jewelry_Necklace_13', 'Bloodlust Brooch', '+1% Power for every 40 kills, up to +6.5%.', 255, 0, 1, 4, '', 'card', 20),
  (60022, 'unhit_power', 'Interface\\Icons\\INV_Jewelry_Talisman_09', 'Talisman of Ascendance', '+1% Power for each second without being hit, up to +20%.', 20, 0, 1, 4, '', 'card', 37),
  (60023, 'rapid_fire', 'Interface\\Icons\\ability_creature_poison_06', 'Rapid Fire', 'Each Hunter''s Mark gives you +15% Haste for 5 sec.', 0, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 30229),
  (60024, 'slice_and_dice', 'Interface\\Icons\\spell_shadow_curseoftounges', 'Slice and Dice', 'Each Eviscerate gives you +15% Haste for 5 sec.', 0, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 40228),
  (60025, 'borrowed_time', 'Interface\\Icons\\spell_holy_auraoflight', 'Borrowed Time', 'After each Power Word: Shield, +15% Haste for 4 sec.', 0, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 50127),
  (60026, 'flurry', 'Interface\\Icons\\ability_ghoulfrenzy', 'Flurry', 'Each Windfury gives +2% Haste for 4 sec.', 0, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 70204),
  (60027, 'lifebloom', 'Interface\\Icons\\Spell_Nature_WispHeal', 'Lifebloom', 'Heals you for 0.3% of your maximum health. Its thorny bloom lashes the 3 nearest enemies for Nature damage. Empowered in Tree of Life. Every 4th bloom heals you for 1% of your maximum health and deals Nature damage to all nearby enemies. Healing past full health makes your spells attack 15% more often for 3 sec.', 0, 28, 1, 0, '', 'weapon', 1028),
  (60028, 'bloodsurge', 'Interface\\Icons\\ability_racial_cannibalize', 'Bloodsurge', 'Each Bleeding enemy that dies gives +1% Power for 8 sec, stacking up to 10 times.', 10, 28, 1, 3, 'Power increased by {1}%.', 'mastery', 10128),
  (60029, 'forceful_winds', 'Interface\\Icons\\spell_nature_earthbind', 'Forceful Winds', 'Each Windfury gives +2% Power for 8 sec, stacking up to 5 times.', 5, 28, 1, 3, 'Power increased by {1}%.', 'mastery', 70229),
  (60030, 'danse_macabre', 'Interface\\Icons\\spell_shadow_summonvoidwalker', 'Danse Macabre', 'Each Ambush gives +1% Power for 8 sec, stacking up to 10 times.', 10, 28, 1, 3, 'Power increased by {1}%.', 'mastery', 40328),
  (60031, 'avenging_wrath', 'Interface\\Icons\\spell_holy_flashheal', 'Avenging Wrath', 'Each Holy spell gives +1% Haste for 6 sec, stacking up to 5 times.', 5, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 20131),
  (60032, 'zealotry', 'Interface\\Icons\\spell_holy_prayerofhealing', 'Zealotry', 'Each Retribution spell gives +1% Haste for 6 sec, stacking up to 10 times.', 10, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 20330),
  (60033, 'arcane_tempo', 'Interface\\Icons\\Spell_Arcane_TeleportMoonglade', 'Arcane Tempo', 'Each Arcane spell gives +1% Haste for 6 sec, stacking up to 5 times.', 5, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 80128),
  (60034, 'starlord', 'Interface\\Icons\\spell_nature_crystalball', 'Starlord', 'Each Starfire gives +3% Haste for 8 sec, stacking up to 3 times.', 3, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 110128),
  (60035, 'soul_of_the_forest', 'Interface\\Icons\\spell_nature_earthshock', 'Soul of the Forest', 'Each rooted enemy that dies gives +1% Haste for 8 sec, stacking up to 10 times.', 10, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 110330),
  (60036, 'harvester_of_souls', 'Interface\\Icons\\spell_shadow_soulgem', 'Harvester of Souls', 'Each enemy that dies with your Decay or Agony on it gives +1% Haste for 8 sec, stacking up to 10 times.', 10, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 90131),
  (60037, 'unrelenting_storm', 'Interface\\Icons\\spell_frost_frostbrand', 'Unrelenting Storm', 'Each Static discharge gives +1% Haste for 6 sec, stacking up to 10 times.', 10, 28, 1, 3, 'Haste increased by {1}%.', 'mastery', 70132),
  (60038, 'mongoose_fury', 'Interface\\Icons\\ability_hunter_pet_spider', 'Mongoose Fury', 'Each Poisoned enemy within 10 yards gives you +1% Haste, up to 10%.', 10, 0, 1, 0, '', 'mastery', 30332),
  (60039, 'bulwark', 'Interface\\Icons\\spell_holy_sealofsacrifice', 'Bulwark of Righteous Fury', 'Each enemy within 10 yards gives you +1% Power, up to 10%.', 10, 0, 1, 0, '', 'mastery', 20228),
