  (60041, 'bloodtalons', 'Interface\\Icons\\ability_druid_swipe', 'Bloodtalons', 'Each Bleeding enemy within 10 yards gives you +1% Power, up to 10%.', 10, 0, 1, 0, '', 'mastery', 110231),
