  (60043, 'demoralizing_roar', 'Interface\\Icons\\Ability_Druid_DemoralizingRoar', 'Demoralizing Roar', 'This enemy deals less damage for a short time.', 0, 28, 1, 0, '', 'none', NULL),
  (60044, 'strangling_vines', 'Interface\\Icons\\Spell_Nature_CorrosiveBreath', 'Strangling Vines', 'Roots grasp the 3 nearest enemies for Nature damage and root them for 2 sec. Empowered in Tree of Life. Rooted enemies take Nature damage every sec, healing you for 0.05% of your maximum health each, up to 0.5% per sec.', 0, 28, 1, 0, '', 'weapon', 1033),
