  (60046, 'schism', 'Interface\\Icons\\spell_holy_blessingofprotection', 'Schism', 'Enemies hit by Penance take 15% more damage from you for 6 sec.', 0, 28, 1, 0, '', 'mastery', 50129),
  (60047, 'hammer_exposed', 'Interface\\Icons\\Spell_Holy_HammerOfWrath', 'Exposed', 'This enemy takes more damage from you for a short time.', 0, 28, 1, 0, '', 'mastery', 20127),
  (60048, 'clearcasting', 'Interface\\Icons\\ability_ambush', 'Clearcasting', 'When Arcane Concentration resets a cooldown, your next spell deals 20% more damage.', 1, 0, 1, 0, '', 'mastery', 80123),
  (60049, 'fingers_of_frost', 'Interface\\Icons\\Spell_Frost_FrostShock', 'Fingers of Frost', 'Frostbolt has a 15% chance to treat its target as Frozen.', 1, 0, 1, 0, '', 'mastery', 80328),
  (60050, 'arcane_potency', 'Interface\\Icons\\Spell_Holy_MagicalSentry', 'Arcane Potency', 'After each Blink, your next 3 spells have 10% more critical strike chance (5 with Improved Arcane Potency).', 0, 0, 1, 0, '', 'mastery', 80124),
  (60051, 'aegis', 'Interface\\Icons\\INV_Shield_06', 'Aegis', 'Adds a Shield of 10% of your maximum health that lasts until it absorbs damage. Each hit it absorbs sends out a shockwave, dealing damage to all enemies within 8 yards of you, at most once every 0.5 sec.', 1, 0, 1, 0, '', 'weapon', 325),
  (60052, 'vanish_crit', 'Interface\\Icons\\Ability_Vanish', 'Glyph of Vanish', 'After you dash, you are immune to damage for 1 sec and your next spell critically strikes.', 1, 0, 1, 0, '', 'glyph', 30),
  (60053, 'heavy_runecloth_bandage', 'Interface\\Icons\\INV_Misc_Bandage_12', 'Heavy Runecloth Bandage', 'After 4 sec without being hit, regain 1.35% of your health every second.', 255, 0, 1, 4, '', 'card', 5),
  (60054, 'basic_campfire', 'Interface\\Icons\\Spell_Fire_Fire', 'Basic Campfire', 'After standing still for 1 sec, regain 1.35% of your health every second.', 255, 0, 1, 4, '', 'card', 6);
INSERT INTO `hoa_aura_locale` (`entry`, `locale`, `name`, `description`, `dynamic_template`)
VALUES
  (12485, 'zhCN', '冰寒', '每层使敌人减速3%，最多30%。叠至10层时敌人被冻结。尚不能被冻结的敌人会停留在10层。每层新叠加都会将冰寒的持续时间刷新为4秒。', ''),
  (18798, 'zhCN', '冻结', '普通敌人被原地冻结2秒。精英和首领仍可移动，但在2秒内视同被冻结。碎裂：你的冰霜法术必定对被冻结的敌人造成致命一击，且对被冻结敌人的每次致命一击额外造成50%的伤害。冻结结束后，该敌人在6秒内无法再次被冻结。', ''),
  (12654, 'zhCN', '燃烧', '每层每跳造成火焰伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。燃烧中的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人，其层数剩余的伤害会爆发到8码内最多4个敌人身上，每个承受一半。', ''),
  (12721, 'zhCN', '流血', '每层每跳造成物理伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。流血中的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人，其层数剩余的伤害会爆发到8码内最多4个敌人身上，每个承受一半。', ''),
  (19448, 'zhCN', '中毒', '每层每跳造成自然伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。中毒的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人，其层数剩余的伤害会爆发到8码内最多4个敌人身上，每个承受一半。', ''),
  (22959, 'zhCN', '火焰易伤', '每层使其受到的火焰伤害提高3%。最多叠加5次。', ''),
  (27991, 'zhCN', '破甲', '每层使其受到的物理伤害提高4%。最多叠加5次。', ''),
  (15258, 'zhCN', '暗影易伤', '每层使其受到的暗影伤害提高3%。最多叠加5次。', ''),
  (20374, 'zhCN', '猎人印记', '被标记的敌人受到你和你的召唤物造成的伤害提高15%，施加标记的法术等级和标记强化最多可将其提高至30%。天赋效果在此基础上另行叠加。被标记的敌人死亡时，标记会转移至10码内最近的2个未被标记的敌人。', ''),
  (13496, 'zhCN', '眩晕', '使敌人减速30%，持续4秒。', ''),
  (18148, 'zhCN', '静电', '最多叠加5次。叠至5层时，闪电会击中该敌人，对其及6码内最多3个敌人造成自然伤害，随后层数重置。', ''),
  (17364, 'zhCN', '自然易伤', '每层使其受到的自然伤害提高4%。最多叠加5次。', ''),
  (594, 'zhCN', '腐朽', '每层每跳造成暗影伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。带有腐朽的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。', ''),
  (14868, 'zhCN', '痛苦', '每层每跳造成暗影伤害。每层在敌人身上每停留一跳，伤害就会增加其初始伤害的四分之一，8跳后最多增至三倍。每个敌人身上只能存在一个诅咒。', ''),
  (8921, 'zhCN', '月火术', '每层每跳造成奥术伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。中了月火术的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。', ''),
  (17, 'zhCN', '护盾状态', '有护盾时移动速度提高10%。', ''),
  (5277, 'zhCN', '闪避', '使你的闪避几率提高50%，持续5秒，最多达到85%。', ''),
  (8233, 'zhCN', '毁灭之风', '挥击最近的敌人，造成伤害。每第3次挥击会唤起风怒：额外挥击2次，同时命中4码内的敌人。每隔15秒，所有挥击都会唤起风怒，持续4秒。', ''),
  (33461, 'zhCN', '灵魂', '每个灵魂使你的伤害提高5%。', ''),
  (60056, 'zhCN', '死疽', '每层使受到的治疗降低5%。', '受到的治疗降低 {1}。'),
  (339, 'zhCN', '定身', '定身2秒。', ''),
  (1833, 'zhCN', '偷袭', '你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。伏击会使普通敌人昏迷1秒。', ''),
  (2070, 'zhCN', '闷棍', '瘫痪2秒。', ''),
  (5116, 'zhCN', '减速', '移动速度降低2秒。', ''),
  (7922, 'zhCN', '昏迷', '昏迷1秒。', ''),
  (8122, 'zhCN', '恐惧', '恐惧逃跑2秒。', ''),
  (9484, 'zhCN', '禁锢', '无法行动2秒。', ''),
  (17498, 'zhCN', '移动速度', '移动速度提高。', ''),
  (19255, 'zhCN', '最大生命值', '最大生命值提高。', ''),
  (20368, 'zhCN', '狂暴', '伤害提高。', ''),
  (21183, 'zhCN', '十字军审判', '以圣光之锤猛击20码内最强的3个敌人，造成神圣伤害，致命一击几率翻倍。被审判的敌人在6秒内受到你造成的伤害提高20%。像审判一样释放你的圣印。', ''),
  (23414, 'zhCN', '虚空之须', '召唤一只暗影魔，其攻击会施加腐朽，并为你恢复0.5%最大生命值。它会每隔6秒定身6码内的普通敌人2秒。', ''),
  (19502, 'zhCN', '瘟疫野兽', '召唤一头亡灵野兽为你而战。它的爪击会施加2层中毒，其瘟疫之云每秒对5码内的敌人施加1层中毒。', ''),
  (19574, 'zhCN', '狂野怒火', '你的宠物始终处于狂热状态：造成的伤害提高50%，且它们的攻击会命中前方的所有敌人。兽群领袖的嚎叫使它们造成的伤害提高25%。你的其他法术造成的伤害降低25%。', ''),
  (28419, 'zhCN', '尖啸', '翼龙的尖啸强化你的宠物。', ''),
  (22518, 'zhCN', '血色', '死亡时留下治疗血池。', ''),
  (22577, 'zhCN', '死疽', '攻击会施加死疽。', ''),
  (22578, 'zhCN', '吸血', '造成伤害时恢复生命。', ''),
  (22579, 'zhCN', '爆炸', '死亡时爆炸。', ''),
  (22580, 'zhCN', '迅捷', '移动速度提高。', ''),
  (22581, 'zhCN', '激励', '死亡时强化附近盟友。', ''),
  (22576, 'zhCN', '坚定', '生命值提高。', ''),
  (26388, 'zhCN', '壁垒', '获得伤害护盾。', ''),
  (28126, 'zhCN', '狂乱', '攻击速度提高。', ''),
  (31309, 'zhCN', '狂怒', '伤害提高。', ''),
  (60055, 'zhCN', '武器宝珠', '一颗武器宝珠环绕着你。', ''),
  (33462, 'zhCN', '狂怒', '急速提高。', '急速提高{1}%。'),
  (33467, 'zhCN', '威慑', '闪避几率提高50%。', ''),
  (33468, 'zhCN', '复苏', '免疫物理伤害。', ''),
  (33463, 'zhCN', '圣盾术', '一个金色气泡环绕你，抵挡敌人的下一次伤害超过5%最大生命值的攻击。', ''),
  (33464, 'zhCN', '恢复', '每秒为你恢复1%最大生命值。生命值全满时，改为惩击30码内最近的敌人，造成神圣伤害。拥有真言术：盾时，超出满生命值的治疗会补充你的护盾，最多补充至护盾上限。', ''),
  (33465, 'zhCN', '闪电之盾', '以最多3层闪电充能环绕你。每1.5秒，每层你所持有的充能会电击1个10码内的敌人，造成自然伤害并叠加1层静电，每次电击还会为你提供相当于最大生命值0.5%的护盾，最多叠加至5%。攻击你的敌人会消耗一层充能并同样被电击。每1.5秒恢复一层充能。', ''),
  (33466, 'zhCN', '剑刃乱舞', '在8秒内，你的单体攻击还会以50%的伤害打击8码内的4个额外敌人。额外攻击会附带你的毒药和起手技。', ''),
  (60001, 'zhCN', '决心', '每层提高你的力量并降低你受到的伤害。', '力量提高 {1}%，受到的伤害降低 {1}%。'),
  (60003, 'zhCN', '首领创伤', '降低你受到的治疗效果。', '受到的治疗降低 {1}。'),
  (60004, 'zhCN', '赞达拉英雄护符', '每30秒获得25%力量，持续10秒。', '力量提高{1}%。'),
  (60005, 'zhCN', '护盾', '吸收受到的伤害。', '吸收 {1} 点伤害。'),
  (60057, 'zhCN', '护盾恢复', '避免受到伤害后护盾将恢复。', '护盾将在{1}秒后恢复。'),
  (60058, 'zhCN', '旋刃', '旋转攻击周围所有敌人。', '旋转{1}秒。每{2}秒攻击一次。'),
  (60059, 'zhCN', '奉献之力', '站在奉献中时伤害提高。', '伤害提高{1}%。'),
  (60060, 'zhCN', '光之守护者', '站在奉献中时受到的伤害降低。', '受到的伤害降低{1}%。'),
  (60061, 'zhCN', '反击', '反击暂时无法触发。', '反击将在{1}秒后可再次触发。'),
  (60062, 'zhCN', '暗影交织', '暗影交织暂时无法触发。', '暗影交织将在{1}秒后可再次触发。'),
  (60063, 'zhCN', '萨满之怒', '萨满之怒暂时无法触发。', '萨满之怒将在{1}秒后可再次触发。'),
  (60064, 'zhCN', '强化冰霜新星', '强化冰霜新星暂时无法触发。', '强化冰霜新星将在{1}秒后可再次触发。'),
  (60006, 'zhCN', '暗月卡片：蓝龙', '你的法术有10%几率使你的急速提高30%，持续6秒。冷却时间20秒。', ''),
  (60007, 'zhCN', '迅捷药水', '生命值降至50%以下时，移动速度提高50%，持续4秒。冷却时间20秒。', ''),
  (60008, 'zhCN', '联盟徽记', '你被击中后的0.5秒内不会受到伤害。冷却时间8秒。', ''),
  (60010, 'zhCN', '尖刺颈饰', '敌人击中你时，荆棘会打击8码内的所有敌人，造成相当于普通难度下普通敌人生命值40%的伤害。每0.5秒至多触发一次。', ''),
  (60012, 'zhCN', '猛虎之怒', '斜掠最近的3个敌人，造成伤害并施加2层流血。猎豹形态下获得强化。每次斜掠每命中一个敌人，使你获得5%急速，持续4秒，最多25%。', ''),
  (60013, 'zhCN', '奥术强化', '在1秒内向最近的敌人发射5枚奥术飞弹，每枚造成奥术伤害。每次闪现术后，会一次性向最近的敌人发射全部5枚，并使你的法术伤害提高30%，持续4秒。', ''),
  (60014, 'zhCN', '暗影之舞', '在4秒内你的攻击造成的伤害提高30%，且可再次触发伏击，每个敌人每秒一次。', ''),
  (60015, 'zhCN', '毒伤', '打击中毒层数最多的3个敌人，造成自然伤害，并附加其中毒效果剩余本应造成的全部伤害，同时保留层数。你的攻击在5秒内额外施加2层中毒。', ''),
  (60016, 'zhCN', '黑暗契约', '吸取16码内最近的敌人，每秒造成伤害并治疗你，每秒至多恢复2%最大生命值。溢出满生命值的治疗会使你的恶魔造成的伤害提高30%，持续4秒。被吸取的敌人受到你的腐朽和痛苦伤害提高20%。', ''),
  (60017, 'zhCN', '灵魂收割雕文', '每击杀50个敌人，你造成的伤害提高至三倍，持续2秒。', ''),
  (60018, 'zhCN', '嗜血雕文', '每击杀50个敌人，获得40%急速，持续8秒。', ''),
  (60019, 'zhCN', '寒冰屏障', '每个阶段一次：生命值降至20%以下时，你会被寒冰包裹，2秒内不受到任何伤害，且10码内的敌人获得10层冰寒。不能与强化冰霜新星同时学习。', ''),
  (60020, 'zhCN', '游牧者雕文', '受到生命伤害时，该效果反转为力量降低25%，持续5秒。被护盾吸收的伤害不计入。', ''),
  (60021, 'zhCN', '嗜血胸针', '每击杀40个敌人，力量提高1%，最多提高6.5%。', ''),
  (60022, 'zhCN', '优越护符', '每持续一秒未被击中，力量提高1%，最多提高20%。', ''),
  (60023, 'zhCN', '急速射击', '每次施放猎人印记，你的急速提高15%，持续5秒。', '急速提高{1}%。'),
  (60024, 'zhCN', '切割', '每次施放剔骨，你的急速提高15%，持续5秒。', '急速提高{1}%。'),
  (60025, 'zhCN', '争分夺秒', '每次施放真言术：盾后，急速提高15%，持续4秒。', '急速提高{1}%。'),
  (60026, 'zhCN', '乱舞', '每次风怒都会使急速提高2%，持续4秒。', '急速提高{1}%。'),
  (60027, 'zhCN', '生命绽放', '为你恢复0.3%最大生命值。其多刺的花朵会抽打最近的3个敌人，造成自然伤害。生命之树形态下获得强化。每第4次绽放会为你恢复1%最大生命值，并对附近所有敌人造成自然伤害。溢出满生命值的治疗会使你的法术攻击频率提高15%，持续3秒。', ''),
  (60028, 'zhCN', '血涌', '每有一个流血的敌人死亡，你的力量提高1%，持续8秒，最多叠加10次。', '力量提高{1}%。'),
  (60029, 'zhCN', '强风', '每次风怒都会使你的力量提高2%，持续8秒，最多叠加5次。', '力量提高{1}%。'),
  (60030, 'zhCN', '断魂之舞', '每次伏击都会使你的力量提高1%，持续8秒，最多叠加10次。', '力量提高{1}%。'),
  (60031, 'zhCN', '复仇之怒', '每次施放神圣系法术，急速提高1%，持续6秒，最多叠加5次。', '急速提高{1}%。'),
  (60032, 'zhCN', '狂热信念', '每次施放惩戒系法术，急速提高1%，持续6秒，最多叠加10次。', '急速提高{1}%。'),
  (60033, 'zhCN', '奥术迅疾', '每次施放奥术系法术，急速提高1%，持续6秒，最多叠加5次。', '急速提高{1}%。'),
  (60034, 'zhCN', '星辰领主', '每次施放星火术，急速提高3%，持续8秒，最多叠加3次。', '急速提高{1}%。'),
  (60035, 'zhCN', '丛林之魂', '每有一个被定身的敌人死亡，急速提高1%，持续8秒，最多叠加10次。', '急速提高{1}%。'),
  (60036, 'zhCN', '灵魂之镰', '每有一个身上带有你的腐朽或痛苦的敌人死亡，急速提高1%，持续8秒，最多叠加10次。', '急速提高{1}%。'),
  (60037, 'zhCN', '冷酷风暴', '每次静电放电都会使急速提高1%，持续6秒，最多叠加10次。', '急速提高{1}%。'),
  (60038, 'zhCN', '猫鼬之怒', '你10码内每有一个中毒的敌人，你的急速就提高1%，最多提高10%。', ''),
  (60039, 'zhCN', '正义之怒壁垒', '你10码内每有一个敌人，你的力量就提高1%，最多提高10%。', ''),
  (60040, 'zhCN', '远古疯狂', '你20码内每有一个染有腐朽的敌人，你的力量就提高1%，最多提高10%。', ''),
  (60041, 'zhCN', '血腥爪击', '你10码内每有一个流血的敌人，你的力量就提高1%，最多提高10%。', ''),
  (60042, 'zhCN', '狂啸', '你的宠物在前方敌人面前造成双倍伤害，持续6秒。', ''),
  (60043, 'zhCN', '挫志咆哮', '短时间内该敌人造成的伤害降低。', ''),
  (60044, 'zhCN', '勒紧藤蔓', '根须缠绕最近的3个敌人，造成自然伤害并使其定身2秒。生命之树形态下获得强化。被定身的敌人每秒受到自然伤害，每有一个敌人为你恢复0.05%最大生命值，每秒最多0.5%。', ''),
  (60045, 'zhCN', '魅惑', '短时间内该敌人受到的伤害翻倍。', ''),
  (60046, 'zhCN', '教派分歧', '被苦修击中的敌人受到你造成的伤害提高15%，持续6秒。', ''),
  (60047, 'zhCN', '破绽', '短时间内该敌人受到的伤害提高。', ''),
  (60048, 'zhCN', '节能施法', '奥术专注重置冷却时间时，你的下一个法术造成的伤害提高20%。', ''),
  (60049, 'zhCN', '寒冰指', '寒冰箭有15%几率将其目标视为已冻结。', ''),
  (60050, 'zhCN', '奥术潜能', '每次闪现后，你接下来的3个法术的致命一击几率提高10%（强化奥术潜能改为5个）。', ''),
  (60051, 'zhCN', '神盾护体', '获得一层护盾，可吸收相当于10%最大生命值的伤害，存留直至吸收伤害。护盾每吸收一次攻击就会发出一道冲击波，对你8码内的所有敌人造成伤害，每0.5秒至多触发一次。', ''),
  (60052, 'zhCN', '消失雕文', '冲刺后，你在1秒内免疫伤害，且你的下一个法术必定造成致命一击。', ''),
  (60053, 'zhCN', '厚符文布绷带', '在4秒内未受到攻击后，每秒恢复1.35%生命值。', ''),
  (60054, 'zhCN', '基础营火', '原地站立1秒后，每秒恢复1.35%生命值。', '');
